<h1 class="text-2xl font-bold">{{ $order->order_number }} · {{ $order->driver?->user?->name ?? 'Unassigned' }}</h1><p id="map-status" class="my-3 text-sm text-slate-600">Loading tracking…</p><div id="track-map" class="z-0 h-[65vh] min-h-80 w-full rounded-xl bg-white"></div>
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
<script>(()=>{const m=L.map('track-map'),s=document.getElementById('map-status');L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(m);let d=null,t=null;async function u(){try{const r=await fetch(@json(route('admin.tracking.data',$order)),{headers:{Accept:'application/json'}});if(!r.ok)throw Error('Tracking unavailable');const x=await r.json();s.textContent=!x.location?'Waiting for first driver GPS location.':!x.fresh?'Driver location is stale.':`Updated ${new Date(x.location.recorded_at).toLocaleTimeString()}`;if(x.destination.latitude!==null&&x.destination.longitude!==null){const p=[+x.destination.latitude,+x.destination.longitude];if(!t)t=L.marker(p).addTo(m).bindPopup('Destination');else t.setLatLng(p)}if(x.location){const p=[+x.location.latitude,+x.location.longitude];if(!d)d=L.marker(p).addTo(m).bindPopup('Driver');else d.setLatLng(p);m.setView(p,14)}else if(t)m.setView(t.getLatLng(),14)}catch(e){s.textContent=e.message}}u();setInterval(u,10000)})();</script>
